package graph

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"reflect"
	"runtime"
	"strings"

	"github.com/tggo/claude-agent-go/claudecli"
	"github.com/tggo/claude-agent-go/runner"
)

// The interfaces below extend Observer. An Observer passed to WithObserver is
// probed for each of them with a type assertion, so implementing any subset is
// enough and existing two-method observers keep working unchanged.

// RunInfo identifies one run to RunObserver. RunID is generated by Run and
// kept by Resume through Checkpoint.RunID, so every segment of a paused and
// resumed run shares it.
type RunInfo struct {
	RunID    string
	Graph    string
	Topology Topology
	// State is the JSON of the state the segment started from (nil when S does
	// not marshal).
	State json.RawMessage
	// Resumed is true for a segment started by Resume.
	Resumed bool
}

// RunObserver is told when a run segment starts and ends. RunStart is called
// by Run and by Resume; RunEnd is called with the segment's Report and error
// (an *Interrupted[S] when the segment paused).
type RunObserver interface {
	RunStart(ctx context.Context, info RunInfo)
	RunEnd(ctx context.Context, info RunInfo, rep *Report, err error)
}

// EdgeObserver is told about every routing decision: the run moved from node
// from to node to (End and Start are pseudo-nodes). step is the execution
// number of from (0 for the edge out of Start). Fan-out edges from a parallel
// node to its branches are reported too, with the parallel node's step.
type EdgeObserver interface {
	EdgeTaken(ctx context.Context, from, to string, step int)
}

// StateObserver receives the state, marshaled with encoding/json, before and
// after each node execution (branches get their private copy). It is called
// just before NodeEnd. A state that does not marshal is skipped silently.
type StateObserver interface {
	NodeState(ctx context.Context, info StepInfo, before, after json.RawMessage)
}

// ResumeObserver is told that Resume is about to re-run info.Node with answer.
type ResumeObserver interface {
	Resumed(ctx context.Context, info StepInfo, answer string)
}

// Gate is consulted before each top-level node executes. It may block (a
// breakpoint) and may fail the run by returning an error, which Run returns
// as is. It is not consulted for parallel branches, nor for the re-run of an
// interrupted node by Resume.
type Gate interface {
	Before(ctx context.Context, info StepInfo) error
}

// AgentObserver receives every stream event of the agent runs made through
// Agent and RunAgent, tagged with the node execution that made them.
type AgentObserver interface {
	AgentEvent(ctx context.Context, info StepInfo, ev claudecli.StreamEvent)
}

// AgentInfo describes one agent invocation made through Agent or RunAgent.
type AgentInfo struct {
	// Input is the secret-free effective configuration (Runner defaults merged
	// with the Input overrides), including the full prompt.
	Input runner.Effective `json:"input"`
	// Retry is set when the invocation runs under WithRetry.
	Retry *RetryInfo `json:"retry,omitempty"`
}

// RetryInfo is the retry policy of an agent invocation.
type RetryInfo struct {
	MaxAttempts int  `json:"max_attempts"`
	Resume      bool `json:"resume"`
}

// AgentInputObserver is told, just before each agent run starts, exactly what
// it will be run with.
type AgentInputObserver interface {
	AgentInput(ctx context.Context, info StepInfo, in AgentInfo)
}

// Node kinds reported by Topology.
const (
	KindStart    = "start"
	KindFunc     = "func"
	KindAgent    = "agent"
	KindParallel = "parallel"
	KindEnd      = "end"
)

// Topology is the static shape of a compiled graph, for visualisers.
type Topology struct {
	Name  string     `json:"name"`
	Entry string     `json:"entry"` // always Start
	Nodes []TopoNode `json:"nodes"`
	Edges []TopoEdge `json:"edges"`
	// MaxSteps and NodeTimeoutMS are the run limits (0 timeout = none).
	MaxSteps      int   `json:"max_steps"`
	NodeTimeoutMS int64 `json:"node_timeout_ms,omitempty"`
}

// TopoNode is one node of a Topology.
type TopoNode struct {
	ID   string `json:"id"`
	Kind string `json:"kind"` // start | func | agent | parallel | end
	// Branches lists the branch nodes of a parallel node.
	Branches []string `json:"branches,omitempty"`
	// Parent is the parallel node a branch belongs to.
	Parent string `json:"parent,omitempty"`
	// Func, File and Line locate the Go function behind the node (for a
	// parallel node, its merge function). Empty for nodes built by Agent, whose
	// function is the SDK's own adapter (Agent, and Func, whose closure hides the
	// user's function).
	Func string `json:"func,omitempty"`
	File string `json:"file,omitempty"`
	Line int    `json:"line,omitempty"`
	// Runner holds the effective defaults of the node's runner, when it was
	// registered with AgentRunner.
	Runner *runner.Effective `json:"runner,omitempty"`
}

// TopoEdge is one declared edge. A conditional edge is listed once per
// declared target. Back marks edges that close a loop (they point at a node
// that is still being explored in a depth-first walk from Start).
type TopoEdge struct {
	From        string `json:"from"`
	To          string `json:"to"`
	Conditional bool   `json:"conditional,omitempty"`
	Label       string `json:"label,omitempty"`
	Back        bool   `json:"back,omitempty"`
}

// Topology describes the compiled graph: nodes (agent nodes are those tagged
// with AddAgentNode or MarkAgent), static and conditional edges, parallel
// fan-out edges, and which edges are loop back-edges.
func (r *Runnable[S]) Topology() Topology {
	t := Topology{Name: r.name, Entry: Start, MaxSteps: r.cfg.maxSteps, NodeTimeoutMS: r.cfg.nodeTimeout.Milliseconds()}
	t.Nodes = append(t.Nodes, TopoNode{ID: Start, Kind: KindStart})
	parentOf := map[string]string{}
	for _, name := range r.order {
		if p := r.nodes[name].par; p != nil {
			for _, b := range p.branches {
				parentOf[b] = name
			}
		}
	}
	for _, name := range r.order {
		n := r.nodes[name]
		tn := TopoNode{ID: name, Kind: KindFunc, Parent: parentOf[name]}
		var fn any = n.fn
		if n.par != nil {
			fn = n.par.merge
		}
		tn.Func, tn.File, tn.Line = funcLocation(fn)
		if n.runner != nil {
			e := n.runner.Effective(runner.Input{})
			tn.Runner = &e
		}
		switch {
		case n.par != nil:
			tn.Kind, tn.Branches = KindParallel, append([]string(nil), n.par.branches...)
		case n.agent:
			tn.Kind = KindAgent
		}
		t.Nodes = append(t.Nodes, tn)
	}
	t.Nodes = append(t.Nodes, TopoNode{ID: End, Kind: KindEnd})

	add := func(from, to string, cond bool) {
		t.Edges = append(t.Edges, TopoEdge{From: from, To: to, Conditional: cond, Label: r.labels[[2]string{from, to}]})
	}
	for _, from := range append([]string{Start}, r.order...) {
		if n := r.nodes[from]; n != nil && n.par != nil {
			for _, b := range n.par.branches {
				t.Edges = append(t.Edges, TopoEdge{From: from, To: b, Label: "branch"})
			}
		}
		if to, ok := r.static[from]; ok {
			add(from, to, false)
		}
		if c, ok := r.cond[from]; ok {
			for _, to := range c.targets {
				add(from, to, true)
			}
		}
	}

	// Back edges: DFS from Start; an edge into a node on the stack closes a loop.
	out := map[string][]int{}
	for i, e := range t.Edges {
		out[e.From] = append(out[e.From], i)
	}
	const (
		white = iota
		grey
		black
	)
	color := map[string]int{}
	var dfs func(string)
	dfs = func(n string) {
		color[n] = grey
		for _, i := range out[n] {
			to := t.Edges[i].To
			switch color[to] {
			case grey:
				t.Edges[i].Back = true
			case white:
				dfs(to)
			}
		}
		color[n] = black
	}
	dfs(Start)
	return t
}

// funcLocation names fn and says where it is defined. The SDK's own
// adapters (Agent, Func) are not interesting to a viewer and give "".
func funcLocation(fn any) (name, file string, line int) {
	v := reflect.ValueOf(fn)
	if !v.IsValid() || v.Kind() != reflect.Func || v.IsNil() {
		return "", "", 0
	}
	f := runtime.FuncForPC(v.Pointer())
	if f == nil || (strings.HasPrefix(f.Name(), "github.com/tggo/claude-agent-go/graph.Agent[") || strings.HasPrefix(f.Name(), "github.com/tggo/claude-agent-go/graph.Func[")) {
		return "", "", 0
	}
	file, line = f.FileLine(f.Entry())
	return f.Name(), file, line
}

func newRunID() string {
	var b [8]byte
	_, _ = rand.Read(b[:])
	return "run-" + hex.EncodeToString(b[:])
}

func snapshot[S any](s *S) json.RawMessage {
	b, err := json.Marshal(s)
	if err != nil {
		return nil
	}
	return b
}
